import{_ as a,c as i,o,j as s,Y as r,t as n}from"./chunks/framework.BNTND4LZ.js";const b=JSON.parse('{"title":"git-mktree | x-cmd man (git man1) | Build a tree-object from ls-tree formatted text","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-mktree - Build a tree-object from ls-tree formatted text","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-mktree | x-cmd man (git man1) | Build a tree-object from ls-tree formatted text"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-mktree - Build a tree-object from ls-tree formatted text"}]]},"headers":[],"params":{"isMan":true,"man":"git-mktree","category":"git man1","desc":"Build a tree-object from ls-tree formatted text"},"relativePath":"git/man1/git-mktree.md","filePath":"git/man1/[man].md"}'),l={name:"git/man1/git-mktree.md"},d={class:"visually-hidden"};function m(t,e,h,c,p,u){return o(),i("div",null,[s("h1",d,n(t.$params.man),1),e[0]||(e[0]=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-mktree - Build a tree-object from ls-tree formatted text</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mktree</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-z] [--missing] [--batch]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Reads standard input in non-recursive <strong>ls-tree</strong> output format, and creates a tree object. The order of the tree entries is normalized by mktree so pre-sorting the input is not required. The object name of the tree object built is written to the standard output.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-z</p><blockquote><p>Read the NUL-terminated <strong>ls-tree -z</strong> output instead.</p></blockquote><p>--missing</p><blockquote><p>Allow missing objects. The default behaviour (without this option) is to verify that each tree entry&#39;s sha1 identifies an existing object. This option has no effect on the treatment of gitlink entries (aka &quot;submodules&quot;) which are always allowed to be missing.</p></blockquote><p>--batch</p><blockquote><p>Allow building of more than one tree object before exiting. Each tree is separated by a single blank line. The final new-line is optional. Note - if the <strong>-z</strong> option is used, lines are terminated with NUL.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>',15))])}const f=a(l,[["render",m]]);export{b as __pageData,f as default};
